from src.api import get_user

def load_user():
    return get_user()

import json
import sys
from pathlib import Path

def send(value):
    print(json.dumps(value), flush=True)

def tool():
    return {'name': 'project_stats', 'description': 'Count Python files and lines in a workspace directory.', 'inputSchema': {'type': 'object', 'properties': {'path': {'type': 'string', 'default': 'src'}}, 'additionalProperties': False}}

for raw in sys.stdin:
    message = json.loads(raw)
    method = message.get('method')
    request_id = message.get('id')
    if method == 'initialize':
        send({'jsonrpc': '2.0', 'id': request_id, 'result': {'protocolVersion': '2025-11-25', 'capabilities': {'tools': {}}, 'serverInfo': {'name': 'eval-stats', 'version': '1'}}})
    elif method == 'tools/list':
        send({'jsonrpc': '2.0', 'id': request_id, 'result': {'tools': [tool()]}})
    elif method == 'tools/call':
        relative = message.get('params', {}).get('arguments', {}).get('path', 'src')
        root = (Path.cwd() / relative).resolve()
        files = list(root.rglob('*.py'))
        lines = sum(len(path.read_text(encoding='utf-8').splitlines()) for path in files)
        text = f'Found {len(files)} Python files with {lines} total lines under {relative}.'
        send({'jsonrpc': '2.0', 'id': request_id, 'result': {'content': [{'type': 'text', 'text': text}], 'structuredContent': {'file_count': len(files), 'line_count': lines}, 'isError': False}})
    elif request_id is not None:
        send({'jsonrpc': '2.0', 'id': request_id, 'result': {}})
